node -e "
const fs = require('fs');
const path = require('path');
const root = 'c:/Users/adiwi/OneDrive/Documents/Personal/Code/CodingCamp-24August26-MRizkiAdiwiganda';

const errors = [];

// Folder rules
const cssFiles = fs.readdirSync(path.join(root,'css'));
const jsFiles  = fs.readdirSync(path.join(root,'js'));
if (cssFiles.length !== 1) errors.push('FAIL css/ must contain exactly 1 file, found: ' + cssFiles.join(', '));
if (jsFiles.length  !== 1) errors.push('FAIL js/  must contain exactly 1 file, found: ' + jsFiles.join(', '));

// Script/link paths in HTML
const html = fs.readFileSync(path.join(root,'index.html'),'utf8');
if (html.includes('src=\"app.js\"'))       errors.push('FAIL stale src=\"app.js\" in index.html — should be js/app.js');
if (html.includes('href=\"styles.css\"'))  errors.push('FAIL stale href=\"styles.css\" in index.html — should be css/styles.css');
if (!html.includes('visibility: hidden'))  errors.push('FAIL flash-prevention inline style missing from index.html');

if (errors.length) { console.error(errors.join('\n')); process.exit(1); }
else { console.log('OK — folder rules and HTML paths valid'); }
"
